(()=>{let t="/web-app-manifest-192x192.png";self.addEventListener("push",e=>{let i={title:"Family Calendar Reminder",body:"You have a new update.",url:"/"};if(e.data)try{i={...i,...e.data.json()}}catch{i.body=e.data.text()}e.waitUntil(self.registration.showNotification(i.title,{body:i.body,icon:t,badge:t,data:{url:i.url||"/"}}))}),self.addEventListener("notificationclick",t=>{t.notification.close();let e=t.notification.data?.url||"/";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let i of t)if(i.url.includes(e)&&"focus"in i)return i.focus();if(self.clients.openWindow)return self.clients.openWindow(e)}))})})();